------------------------------------------------- import
local KTool                = CS.Engine.Lib.KTool
local KCookie              = CS.Engine.Lib.KCookie
local UIModule             = CS.Engine.UI.UIModule
local BehaviourAction      = CS.Engine.Lib.BehaviourAction
---@type ActivityUtils
local ActivityUtils        = import("Game.Activity.ActivityUtils")
local RechargeCellNodePath = "Game.UI.ActivityMainDialog.UIActivityAccumulatedRechargeCellNode"

---@class UIActivityAccumulatedRechargePanel
---@field TxtPlayState                  	UnityEngine.RectTransform
---@field BtnRoleNameNode               	UnityEngine.RectTransform
---@field LoopListCell                  	SuperScrollView.LoopListView2
---@field Text                          	UnityEngine.UI.Text
---@field TxtTime                       	TMPro.TextMeshProUGUI
---@field ImgTitleName                  	UnityEngine.UI.RawImage
---@field ImgRole                       	UnityEngine.RectTransform
local UIActivityAccumulatedRechargePanel = Class("UIActivityAccumulatedRechargePanel")


function UIActivityAccumulatedRechargePanel:__init()
    ---@type ActivityDojo
    self.activityDojo_ = nil  -- 基础活动信息
    self.rechargeData_ = nil  -- 累充活动信息
end


function UIActivityAccumulatedRechargePanel:__delete()
    self.activityDojo_ = nil
    self.rechargeData_ = nil
    self.controller    = nil
end

function UIActivityAccumulatedRechargePanel:Awake()
    -- add listens
    SetButtonAction(self.TxtPlayState, Bind(self, self.OnClickRuleIntroHandler_))
    self.sdkEventHandler_ = Events.AddListener(Constants.EventNames.EVENT_SDK, Bind(self, self.OnSdkEventHandler_))

    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.OnEnableAction = Bind(self, self.OnEnable)
        self.behaviourAction = behaviourAction
    end
end

function UIActivityAccumulatedRechargePanel:OnEnable()
    KTool.SetActive(self.BtnRoleNameNode, false)
end

function UIActivityAccumulatedRechargePanel:Start()
end


function UIActivityAccumulatedRechargePanel:OnDestroy()
    Events.RemoveListener(Constants.EventNames.EVENT_SDK, self.sdkEventHandler_)
    self.controller = nil --删除lua层引⽤用到的c#对象
    self:Delete()
end

function UIActivityAccumulatedRechargePanel:GetItemShowNum()
    return checkInt(self.itemShowNum)
end


------------------------------------------------- public

function UIActivityAccumulatedRechargePanel:Refresh(activityDojo)
    -- update activityDojo
    self.activityDojo_ = activityDojo

    -- request rechargeData
    GameUtils.Request(Interfaces.ActivityAccumulativePay, {activityUuid = activityDojo.id},
        function(request, response)
            if checkNumber(response.errCode) == 0 then
                -- update rechargeData
                self.rechargeData_ = checkTable(response.data)
                self.animMapList_  = {}

                -- sort listData
                table.sort(self.rechargeData_.accumulativePay, function(aData, bData)
                    local aStatus = checkInt(aData.status)
                    local bStatus = checkInt(bData.status)
                    if aStatus == bStatus then
                        return checkInt(aData.amount) < checkInt(bData.amount)
                    else
                        if aStatus == Constants.GetStatus.Has or bStatus == Constants.GetStatus.Has then
                            return aStatus < bStatus
                        else
                            return aStatus > bStatus
                        end
                    end
                end)

                -- init views
                self:RefreshView_()
            end
        end
    )
end


------------------------------------------------- private

function UIActivityAccumulatedRechargePanel:RefreshView_()
    self:RefreshActivityInfo_()
    self:RefreshRewardDrawInfo_()
    self:RefreshCurrencyBarInfo()
    self:RefreshRechargeTaskList_()
    self:RefreshRedPointState_()
end


function UIActivityAccumulatedRechargePanel:RefreshActivityInfo_()
    -- update time
    local startTime = self.activityDojo_.startTime
    local endedTime = self.activityDojo_.endTime
    CfUtils.FillText(self.TxtTime, ActivityUtils.ConventActivityDurationTime(startTime, endedTime))

    -- update title
    local titleImgUrl = checkString(self.activityDojo_.titleImage)
    if string.len(titleImgUrl) > 0 then
        CfUtils.FillWebRawImage(self.ImgTitleName, titleImgUrl)
    end

    -- update detail
    CfUtils.FillText(self.Text, self.activityDojo_.detail)
end


function UIActivityAccumulatedRechargePanel:RefreshRewardDrawInfo_()
    local confDefines  = checkTable(self.rechargeData_.accumulativePayConf)
    local goodsType    = GoodsUtils.GetIdType(confDefines.rewardId)
    local isCardOrSkin = goodsType == Constants.IDType.CharacterCard or goodsType == Constants.IDType.CardSkin
    
    if isCardOrSkin then
        KTool.SetActive(self.ImgRole, true)
        CfUtils.FillRoleImage(self.ImgRole, confDefines.rewardId + 6, Vector2(-210, 210))
        --CfUtils.FillImage(self.ImgRole, ActivityUtils.GetImageFullPath(confDefines.rewardImg))
    end

    if isCardOrSkin then
        KTool.SetActive(self.BtnRoleNameNode, true)
        ---@type CommonBtnRoleNameNode
        local env = CfUtils.GetLuaScr(self.BtnRoleNameNode, "Game.UI.Common.CommonBtnRoleNameNode")
        if env then
            env:RefreshSelf(confDefines.rewardId, nil, function ()
                KCookie.Set(Constants.UICacheDataKeys.UI_ACTIVITY_MAIN_SELECTED_ACTIVITY_ID, self.activityDojo_.id)
            end, true)
        end
    end
end


function UIActivityAccumulatedRechargePanel:RefreshCurrencyBarInfo()
    local confDefines  = checkTable(self.rechargeData_.accumulativePayConf)
    ActivityUtils.RefreshNavigatorGoods(confDefines.itemId)
end


function UIActivityAccumulatedRechargePanel:RefreshRechargeTaskList_()
    -- reload list
    local rechargeTaskList = checkTable(self.rechargeData_.accumulativePay)
    local rechargeTaskSize = #rechargeTaskList

    -- check empty list
    if rechargeTaskSize == 0 then
        return
    end

    self.cellTargetIndex = 0
    for listIndex, listData in ipairs(rechargeTaskList) do
        if checkInt(listData.status) == Constants.GetStatus.Can then
            self.cellTargetIndex = listIndex - 1
            break
        end
    end

    if not self.LoopListCell.IsListViewInit then
        self.LoopListCell:InitListView(rechargeTaskSize, Bind(self, self.OnUpdateTaskListCellHandler_),{mTargetIndex = self.cellTargetIndex})
    else
        self.LoopListCell:MovePanelToItemIndex(self.cellTargetIndex)
    end
end


function UIActivityAccumulatedRechargePanel:RefreshRedPointState_()
    local isOpenRedPoint   = false
    local rechargeTaskList = checkTable(self.rechargeData_.accumulativePay)
    for _, listData in ipairs(rechargeTaskList) do
        if checkInt(listData.status) == Constants.GetStatus.Can then
            isOpenRedPoint = true
            break
        end
    end
    ActivityUtils.UpdateActivityMainRedPointState(self.activityDojo_.id, isOpenRedPoint and 0 or -1)
end


------------------------------------------------- handler

function UIActivityAccumulatedRechargePanel:OnClickRuleIntroHandler_()
    if self.rechargeData_ then
        local confDefines  = checkTable(self.rechargeData_.accumulativePayConf)
        CfUtils.ShowModuleToast(confDefines.ruleId)
    end
end

function UIActivityAccumulatedRechargePanel:OnUpdateTaskListCellHandler_(listView, listIndex)
    if listIndex < 0 then return end
    local cell = listView:NewListViewItem("Cell")
    ---@type UIActivityAccumulatedRechargeCellNode
    local nodeEnv = CfUtils.GetLuaScr(cell.gameObject, RechargeCellNodePath)
    if nodeEnv then
        local recharge = checkInt(self.rechargeData_.playerAmount)
        local taskList = checkTable(self.rechargeData_.accumulativePay)
        local luaIndex = listIndex + 1
        local cellData = checkTable(taskList[luaIndex])
        -- init cell
        nodeEnv:SetLuaIndex(luaIndex)
        nodeEnv:SetPayAmount(recharge)
        nodeEnv:SetCellData(cellData)  -- has refresh
        nodeEnv:SetClickCB(Bind(self, self.OnClickTaskListCellCallback_))
        -- init anim
        if self:GetItemShowNum() <= 0 then
            local cellSizeH  = cell.CachedRectTransform.rect.height + cell.Padding
            local totalNum   = self.LoopListCell.ItemTotalCount
            self.itemShowNum = math.ceil(self.LoopListCell.ViewPortHeight / cellSizeH)
            self.animInitPos = math.max(0, math.min(self.cellTargetIndex, totalNum - self:GetItemShowNum()))
            self.animEndPos  = math.min((self:GetItemShowNum() + self.cellTargetIndex), totalNum)
        end

        if not self.animMapList_[listIndex + 1] and listIndex <=  self.animEndPos and listIndex >= self.animInitPos then
            self.animMapList_[listIndex + 1] = true
            nodeEnv:PlayAnimByEnter(listIndex - self.animInitPos)
        else
            nodeEnv:PlayAnimByShowed()
        end
    end
    return cell
end


function UIActivityAccumulatedRechargePanel:OnClickTaskListCellCallback_(luaIndex)
    local taskList = checkTable(self.rechargeData_.accumulativePay)
    local cellData = checkTable(taskList[luaIndex])
    local statusId = checkInt(cellData.status)

    if statusId == Constants.GetStatus.Not then
        local StoreUtils     = import('Game.UI.Store.StoreUtils')
        local StoreConstants = import('Game.UI.Store.StoreConstants')
        StoreUtils.OpenStore(StoreConstants.OpenIds.StoreCharge)

    elseif statusId == Constants.GetStatus.Can then
        GameUtils.Request(Interfaces.ActivityAccumulativePayDraw, { activityUuid = self.activityDojo_.id, rewardId = cellData.id },
            function(request, response)
                if checkNumber(response.errCode) == 0 then
                    -- draw rewards
                    local rewardList = checkTable(response.data.rewards)
                    GoodsUtils.DrawRewards(rewardList, true)
                    UIModule.OpenDialog({
                        id = Constants.UITypeIds.UICommonRewardPop,
                        parameters = { rewards = rewardList }
                    })

                    -- refresh cell data
                    cellData.status = Constants.GetStatus.Has
                    
                    -- refresh cell node
                    for itemCount = 1, self.LoopListCell.ShownItemCount do
                        local cellNode = self.LoopListCell:GetShownItemByIndex(itemCount - 1)
                        if not isNull(cellNode) then
                            ---@type UIActivityAccumulatedRechargeCellNode
                            local nodeEnv = CfUtils.GetLuaScr(cellNode, RechargeCellNodePath)
                            if nodeEnv then
                                local cellLuaIndex  = nodeEnv:GetLuaIndex()
                                if cellLuaIndex == luaIndex then
                                    nodeEnv:SetCellData(cellData)
                                    break
                                end
                            end
                        end
                    end

                    -- refresh red point
                    self:RefreshRedPointState_()
                end
            end
        )

    elseif statusId == Constants.GetStatus.Has then
        GameUtils.Toast(localize('已领取'))
    end
end


function UIActivityAccumulatedRechargePanel:OnSdkEventHandler_(parameters)
    -- sdk pay succeed
    if parameters.event == Constants.EventNames.EVENT_SDK_PAY then
        -- refresh recharge amount
        self:Refresh(self.activityDojo_)
    end
end


return UIActivityAccumulatedRechargePanel
